import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        if (s.startsWith("dot") || s.startsWith("at") || s.endsWith("at") || s.endsWith("dot")) {
            String result = s;

            if (result.startsWith("dot")) {
                String t = result.substring(3);
                String[] a = t.split("dot");
                String l = String.join(".", a);
                int b = l.indexOf("at");
                String o = l.substring(0, b) + "@" + l.substring(b + 2);
                String q = "dot" + o;
                if (q.endsWith(".")) {
                    String aPart = q.substring(0, q.length() - 1);
                    result = aPart + "dot";
                } else if (q.endsWith("@")) {
                    String aPart = q.substring(0, q.length() - 1);
                    result = aPart + "at";
                } else {
                    result = q;
                }
            }

            if (result.startsWith("at")) {
                String t = result.substring(2);
                String[] a = t.split("dot");
                String l = String.join(".", a);
                int b = l.indexOf("at");
                String o = l.substring(0, b) + "@" + l.substring(b + 2);
                String q = "at" + o;
                if (q.endsWith(".")) {
                    String aPart = q.substring(0, q.length() - 1);
                    result = aPart + "dot";
                } else if (q.endsWith("@")) {
                    String aPart = q.substring(0, q.length() - 1);
                    result = aPart + "at";
                } else {
                    result = q;
                }
            }

            if (result.length() >= 3 && result.substring(result.length() - 3).equals("dot")
                    && !result.startsWith("dot") && !result.startsWith("at")) {
                String t = result.substring(0, result.length() - 3);
                String[] a = t.split("dot");
                String l = String.join(".", a);
                int b = l.indexOf("at");
                String q = l.substring(0, b) + "@" + l.substring(b + 2);
                result = q + "dot";
            }

            if (result.length() >= 2 && result.substring(result.length() - 2).equals("at")
                    && !result.startsWith("dot") && !result.startsWith("at")) {
                String t = result.substring(0, result.length() - 2);
                String[] a = t.split("dot");
                String l = String.join(".", a);
                int b = l.indexOf("at");
                String q = l.substring(0, b) + "@" + l.substring(b + 2);
                result = q + "at";
            }

            System.out.println(result);
        } else {
            String[] a = s.split("dot");
            String l = String.join(".", a);
            int b = l.indexOf("at");
            String q = l.substring(0, b) + "@" + l.substring(b + 2);
            System.out.println(q);
        }
        scanner.close();
    }
}
